  await check('Criar NPC',async()=>{ids.npc=(await gm.req(`/api/chronicles/${cid}/npcs`,{method:'POST',body:{name:'Silas',type:'Vampiro',importance:'important',imageUrl:uploads.avatar,description:'Informante',defense:3,health:5,damage:2,pools:{persuasao:6}},expected:201})).data.id});
  await check('Criar token dos três jogadores + NPC',async()=>{obj.t1=(await gm.req(`/api/vtt/scenes/${scene.porto}/tokens`,{method:'POST',body:{characterId:chars.p1,ownerUserId:U.p1.id,name:'Helena',imageUrl:uploads.avatar,x:180,y:400,width:70,height:70,visionEnabled:true,visionRange:500,disposition:'friendly',bar1Value:3,bar1Max:5,status:['focused']},expected:201})).data.id;obj.t2=(await gm.req(`/api/vtt/scenes/${scene.porto}/tokens`,{method:'POST',body:{characterId:chars.p2,ownerUserId:U.p2.id,name:'Davi',x:260,y:400,width:70,height:70,visionEnabled:true,visionRange:450,disposition:'friendly'},expected:201})).data.id;obj.t3=(await gm.req(`/api/vtt/scenes/${scene.porto}/tokens`,{method:'POST',body:{characterId:chars.p3,ownerUserId:U.p3.id,name:'Lívia',x:340,y:400,width:70,height:70,visionEnabled:true,visionRange:420,disposition:'friendly'},expected:201})).data.id;obj.npcTok=(await gm.req(`/api/vtt/scenes/${scene.porto}/tokens`,{method:'POST',body:{npcId:ids.npc,name:'Silas',x:900,y:450,width:70,height:70,visionEnabled:false,disposition:'neutral'},expected:201})).data.id});
  await check('Criar tile under/over/GM e filtrar GM layer do jogador',async()=>{obj.tileUnder=(await gm.req(`/api/vtt/scenes/${scene.porto}/tiles`,{method:'POST',body:{name:'Mesa',imageUrl:uploads.map,x:600,y:400,width:200,height:120,layer:'under'},expected:201})).data.id;obj.tileOver=(await gm.req(`/api/vtt/scenes/${scene.porto}/tiles`,{method:'POST',body:{name:'Fumaça',imageUrl:uploads.map,x:700,y:300,width:250,height:180,layer:'over',opacity:.5},expected:201})).data.id;obj.tileGm=(await gm.req(`/api/vtt/scenes/${scene.porto}/tiles`,{method:'POST',body:{name:'Segredo',imageUrl:uploads.map,x:1000,y:200,width:100,height:100,layer:'gm'},expected:201})).data.id;const r=await p1.req(`/api/vtt/scenes/${scene.porto}`,{expected:200});assert.ok(!r.data.objects.tiles.some(x=>x.id===obj.tileGm))});
