  await check('Jogador cria nota privada ao Mestre',async()=>{ids.playerNote=(await p1.req(`/api/chronicles/${cid}/notes`,{method:'POST',body:{title:'Desconfiança',content:'Acho que Silas mente',visibility:'all'},expected:201})).data.id;const a=await p2.req(`/api/chronicles/${cid}/notes`,{expected:200});const g=await gm.req(`/api/chronicles/${cid}/notes`,{expected:200});assert.ok(!a.data.notes.some(n=>n.id===ids.playerNote));assert.ok(g.data.notes.some(n=>n.id===ids.playerNote))});
  await check('Chat geral, notas e sussurro isolado',async()=>{await p1.req(`/api/chronicles/${cid}/messages`,{method:'POST',body:{channel:'general',content:'Eu examino a caixa.'},expected:201});await gm.req(`/api/chronicles/${cid}/messages`,{method:'POST',body:{channel:'notes',content:'Teste de percepção.'},expected:201});await p1.req(`/api/chronicles/${cid}/messages`,{method:'POST',body:{channel:'whisper',recipientId:U.gm.id,content:'Quero fazer isso escondido.'},expected:201});const a=await gm.req(`/api/chronicles/${cid}/messages`,{expected:200});const b=await p2.req(`/api/chronicles/${cid}/messages`,{expected:200});assert.ok(a.data.messages.some(m=>m.channel==='whisper'));assert.ok(!b.data.messages.some(m=>m.channel==='whisper'))});
