  await check('Story temporada/episódio/ato/cena',async()=>{ids.season=(await gm.req(`/api/chronicles/${cid}/story`,{method:'POST',body:{nodeType:'season',title:'Temporada 1',position:1},expected:201})).data.id;ids.episode=(await gm.req(`/api/chronicles/${cid}/story`,{method:'POST',body:{nodeType:'episode',parentId:ids.season,title:'Porto de Sangue',position:1},expected:201})).data.id;ids.act=(await gm.req(`/api/chronicles/${cid}/story`,{method:'POST',body:{nodeType:'act',parentId:ids.episode,title:'Ato I',position:1},expected:201})).data.id;ids.storyScene=(await gm.req(`/api/chronicles/${cid}/story`,{method:'POST',body:{nodeType:'scene',parentId:ids.act,title:'O Armazém',position:1},expected:201})).data.id});
