  await check('Jogador não cria token/tile/wall/luz/som/nota/região',async()=>{for(const type of ['tokens','tiles','walls','lights','sounds','map-notes','regions']) await p1.req(`/api/vtt/scenes/${scene.co}/${type}`,{method:'POST',body:{name:'x',x1:0,y1:0,x2:10,y2:10},expected:403})});
  await check('Espectador não movimenta token',async()=>{const tok=(await gm.req(`/api/vtt/scenes/${scene.co}/tokens`,{method:'POST',body:{name:'Spectator target',ownerUserId:U.spec.id,x:100,y:100},expected:201})).data.id;await spec.req(`/api/vtt/tokens/${tok}`,{method:'PATCH',body:{x:200,y:200},expected:403})});
  await check('Jogador não apaga ping de outro',async()=>{const ping=(await p2.req(`/api/vtt/scenes/${scene.co}/pings`,{method:'POST',body:{x:10,y:10},expected:201})).data.id;await p1.req(`/api/vtt/pings/${ping}`,{method:'DELETE',expected:403});await p2.req(`/api/vtt/pings/${ping}`,{method:'DELETE',expected:200})});
  await check('Mestre limpa marcações sem apagar tokens/tiles',async()=>{const dr=(await p1.req(`/api/vtt/scenes/${scene.co}/drawings`,{method:'POST',body:{drawingType:'rect',x:20,y:20,width:50,height:50},expected:201})).data.id;const tok=(await gm.req(`/api/vtt/scenes/${scene.co}/tokens`,{method:'POST',body:{name:'Preservado'},expected:201})).data.id;const tile=(await gm.req(`/api/vtt/scenes/${scene.co}/tiles`,{method:'POST',body:{name:'Preservado',imageUrl:uploads.map},expected:201})).data.id;await gm.req(`/api/vtt/scenes/${scene.co}/clear-markings`,{method:'POST',body:{},expected:200});const r=await gm.req(`/api/vtt/scenes/${scene.co}`,{expected:200});assert.ok(r.data.objects.tokens.some(x=>x.id===tok));assert.ok(r.data.objects.tiles.some(x=>x.id===tile));assert.ok(!r.data.objects.drawings.some(x=>x.id===dr))});
  await check('Co-Mestre pode pausar e retomar',async()=>{await co.req(`/api/vtt/chronicles/${cid}/pause`,{method:'POST',body:{paused:true},expected:200});let b=await p1.req(`/api/vtt/chronicles/${cid}/bootstrap`,{expected:200});assert.equal(b.data.world.paused,true);await co.req(`/api/vtt/chronicles/${cid}/pause`,{method:'POST',body:{paused:false},expected:200})});
