await group(9,'Sessão longa: carga, concorrência, histórico, cursores e estabilidade',async()=>{
  await check('Ativar cena de carga',async()=>await gm.req(`/api/vtt/scenes/${scene.porto}/activate`,{method:'POST',body:{},expected:200}));
  await check('50 mensagens concorrentes sem perda',async()=>{const calls=[];for(let i=0;i<50;i++) calls.push((i%2?p1:p2).req(`/api/chronicles/${cid}/messages`,{method:'POST',body:{channel:'general',content:`Mensagem carga ${i}`},expected:201}));await Promise.all(calls);const r=await gm.req(`/api/chronicles/${cid}/messages`,{expected:200});assert.ok(r.data.messages.filter(m=>m.content.startsWith('Mensagem carga')).length>=50)});
  await check('30 pings/FX concorrentes',async()=>{const calls=[];for(let i=0;i<30;i++)calls.push((i%3===0?gm:p1).req(`/api/vtt/scenes/${scene.porto}/pings`,{method:'POST',body:{x:100+i*10,y:200+i,pingType:i%3===0?'fx':'ping'},expected:201}));await Promise.all(calls);const r=await gm.req(`/api/vtt/scenes/${scene.porto}`,{expected:200});assert.ok(r.data.pings.length<=30)});
  await check('25 rolagens concorrentes de jogadores',async()=>{const calls=[];for(let i=0;i<25;i++){const cl=[p1,p2,p3][i%3];const ch=[chars.p1,chars.p2,chars.p3][i%3];calls.push(cl.req(`/api/vtt/chronicles/${cid}/rolls`,{method:'POST',body:{characterId:ch,pool:6,hunger:2,difficulty:3},expected:201}));}await Promise.all(calls);const r=await gm.req(`/api/vtt/chronicles/${cid}/rolls`,{expected:200});assert.ok(r.data.rolls.length>=25)});
  await check('Explorer concorrente mantém isolamento',async()=>{await gm.req(`/api/vtt/scenes/${scene.porto}`,{method:'PATCH',body:{explorerEnabled:true,fogEnabled:true},expected:200});const calls=[];for(let i=0;i<15;i++)calls.push(p2.req(`/api/vtt/scenes/${scene.porto}/fog`,{method:'PUT',body:{scope:'user',tokenId:obj.t2},expected:200}));for(let i=0;i<17;i++)calls.push(p3.req(`/api/vtt/scenes/${scene.porto}/fog`,{method:'PUT',body:{scope:'user',tokenId:obj.t3},expected:200}));await Promise.all(calls);const a=await p2.req(`/api/vtt/scenes/${scene.porto}`,{expected:200});const b=await p3.req(`/api/vtt/scenes/${scene.porto}`,{expected:200});assert.notDeepEqual(a.data.fog.user.explored,b.data.fog.user.explored)});
  await check('100 atualizações de presença/cursor não quebram bootstrap',async()=>{const calls=[];for(let i=0;i<100;i++){const cl=[p1,p2,p3,co][i%4];calls.push(cl.req(`/api/vtt/chronicles/${cid}/presence`,{method:'POST',body:{sceneId:scene.porto,cursorX:i*3,cursorY:i*2},expected:200}));}await Promise.all(calls);const b=await gm.req(`/api/vtt/chronicles/${cid}/bootstrap`,{expected:200});assert.equal(b.data.members.length,6)});
  await check('Bootstrap em estado carregado responde e contém diretórios',async()=>{const t=Date.now();const b=await gm.req(`/api/vtt/chronicles/${cid}/bootstrap`,{expected:200});const ms=Date.now()-t;assert.ok(Array.isArray(b.data.items)&&Array.isArray(b.data.tables)&&Array.isArray(b.data.decks)&&Array.isArray(b.data.macros));assert.ok(ms<3000,`bootstrap ${ms}ms`)});
  await check('Chat incremental after funciona',async()=>{const all=await p1.req(`/api/chronicles/${cid}/messages`,{expected:200});const last=all.data.messages.at(-1)?.id||0;await p2.req(`/api/chronicles/${cid}/messages`,{method:'POST',body:{content:'incremental-final'},expected:201});const inc=await p1.req(`/api/chronicles/${cid}/messages?after=${last}`,{expected:200});assert.equal(inc.data.messages.length,1);assert.equal(inc.data.messages[0].content,'incremental-final')});
});

await group(10,'Finale: progressão, encerramento, reinício e integridade de campanha',async()=>{
  await check('Atualizar recursos finais das fichas',async()=>{await gm.req(`/api/characters/${chars.p1}`,{method:'PATCH',body:{hunger:4,humanity:6,stains:2,healthCurrent:1,willpowerCurrent:2},expected:200});await gm.req(`/api/characters/${chars.p2}`,{method:'PATCH',body:{hunger:1,humanity:7,healthCurrent:2},expected:200});await gm.req(`/api/characters/${chars.p3}`,{method:'PATCH',body:{hunger:3,humanity:8,willpowerCurrent:1},expected:200})});
  await check('XP final para todos',async()=>{for(const ch of Object.values(chars)) await gm.req(`/api/characters/${ch}/xp`,{method:'POST',body:{amount:5,reason:'Final da campanha'},expected:200})});
  await check('Relógio completa e conflito encerra',async()=>{await gm.req(`/api/clocks/${ids.clock}`,{method:'PATCH',body:{progress:6},expected:200});await gm.req(`/api/conflicts/${ids.conflict}`,{method:'PATCH',body:{round:4,status:'finished',notes:'Conflito encerrado'},expected:200})});
  await check('Recap final no Diário e Timeline',async()=>{ids.recap=(await gm.req(`/api/chronicles/${cid}/diary`,{method:'POST',body:{entryType:'session',title:'Sessão 10 — Finale',content:'A campanha terminou.',visibility:'all',occurredAt:'2026-08-28'},expected:201})).data.id;await gm.req(`/api/chronicles/${cid}/timeline`,{method:'POST',body:{title:'Fim da Crônica',content:'Os personagens sobrevivem.',visibility:'all'},expected:201})});
  await check('Cutscene final lança e encerra',async()=>{await gm.req(`/api/cutscenes/${ids.cut}/launch`,{method:'POST',body:{},expected:200});let live=await p3.req(`/api/chronicles/${cid}/live`,{expected:200});assert.ok(live.data.cutscene);await gm.req(`/api/cutscenes/${ids.cut}/end`,{method:'POST',body:{},expected:200})});
  await check('Crônica marcada como encerrada',async()=>{await gm.req(`/api/chronicles/${cid}`,{method:'PATCH',body:{status:'finished'},expected:200});const r=await p1.req(`/api/chronicles/${cid}`,{expected:200});assert.equal(r.data.chronicle.status,'finished')});
  await check('Logout invalida sessão e login restaura',async()=>{await p1.req('/api/logout',{method:'POST',body:{},expected:200});await p1.req('/api/me',{expected:401});await p1.req('/api/login',{method:'POST',body:{email:'alice@campanha.test',password:'senha1234'},expected:200});await p1.req('/api/me',{expected:200})});
  await check('Estado antes do restart está completo',async()=>{const b=await gm.req(`/api/vtt/chronicles/${cid}/bootstrap`,{expected:200});assert.ok(b.data.scenes.length>=5);assert.ok(b.data.characters.length===3);assert.ok(b.data.rolls.length>=25)});
  await check('Reiniciar servidor preserva banco e uploads',async()=>{await stopServer();await startServer();const g2=client('GM-RELOGIN');await g2.req('/api/login',{method:'POST',body:{email:'gm@campanha.test',password:'senha1234'},expected:200});const c=await g2.req(`/api/chronicles/${cid}`,{expected:200});assert.equal(c.data.chronicle.status,'finished');const b=await g2.req(`/api/vtt/chronicles/${cid}/bootstrap`,{expected:200});assert.equal(b.data.characters.length,3);const file=await fetch(BASE+uploads.video);assert.equal(file.status,200);assert.match(file.headers.get('content-type')||'',/video\/mp4/)});
  await check('Jogadores relogam após restart e veem histórico',async()=>{const a=client('A-RELOGIN');await a.req('/api/login',{method:'POST',body:{email:'alice@campanha.test',password:'senha1234'},expected:200});const d=await a.req(`/api/chronicles/${cid}/diary`,{expected:200});assert.ok(d.data.items.some(x=>x.id===ids.recap));const rr=await a.req(`/api/vtt/chronicles/${cid}/rolls`,{expected:200});assert.ok(rr.data.rolls.length>0)});
  await check('SQLite integrity_check e foreign_key_check limpos',async()=>{const db=new DatabaseSync(path.join(ROOT,'data','elysium.db'));const integrity=db.prepare('PRAGMA integrity_check').get();assert.equal(integrity.integrity_check,'ok');const fk=db.prepare('PRAGMA foreign_key_check').all();assert.equal(fk.length,0);db.close()});
  await check('Crescimento de dados da campanha é coerente',async()=>{const db=new DatabaseSync(path.join(ROOT,'data','elysium.db'));const counts={users:db.prepare('SELECT COUNT(*) n FROM users').get().n,scenes:db.prepare('SELECT COUNT(*) n FROM scenes WHERE chronicle_id=?').get(cid).n,rolls:db.prepare('SELECT COUNT(*) n FROM rolls WHERE chronicle_id=?').get(cid).n,messages:db.prepare('SELECT COUNT(*) n FROM messages WHERE chronicle_id=?').get(cid).n};db.close();assert.equal(counts.users,7);assert.ok(counts.scenes>=5);assert.ok(counts.rolls>=25);assert.ok(counts.messages>=50)});
  await check('Cascade de exclusão em Crônica descartável',async()=>{const z=client('Z');await z.req('/api/login',{method:'POST',body:{email:'gm@campanha.test',password:'senha1234'},expected:200});const c=(await z.req('/api/chronicles',{method:'POST',body:{name:'Descartável'},expected:201})).data.chronicle.id;const s=(await z.req(`/api/vtt/chronicles/${c}/scenes`,{method:'POST',body:{title:'Tmp'},expected:201})).data.id;await z.req(`/api/vtt/scenes/${s}/tokens`,{method:'POST',body:{name:'Tmp'},expected:201});await z.req(`/api/chronicles/${c}`,{method:'DELETE',expected:200});const db=new DatabaseSync(path.join(ROOT,'data','elysium.db'));assert.equal(db.prepare('SELECT COUNT(*) n FROM scenes WHERE chronicle_id=?').get(c).n,0);assert.equal(db.prepare('SELECT COUNT(*) n FROM vtt_tokens WHERE chronicle_id=?').get(c).n,0);db.close()});
});

